functions.body:
block([row, A, pivots],
    row:1,
    pivots: sort(pivots_cols),
    A:zeromatrix(m,n),
    for i thru length(pivots) do(
        piv: pivots[i],
        A[row][piv]:1,
        for j:piv+1 thru n do (
            A[row][j]:rand_with_prohib(min_val,max_val,[])
            ),
        row:row+1
        ),
     for i thru length(pivots) do(
        piv: pivots[i],
        for j:1 thru i-1 do (
            A[j][piv]:0
            )
        ),
    A)

prts.feedbackvariables:
flag5:false;
nullity: length(nullSpaceBase);
if is(isSolvable=0) then flag5:true;

nullityS: if is(isSolvable=1) then length(ans5) else -1;

if is(isSolvable=1) then (nullSpaceBaseMatrixSt:zeromatrix(n,1),for i thru nullityS
do(nullSpaceBaseMatrixSt:addcol(nullSpaceBaseMatrixSt, ans5[i])),
if is(rank(nullSpaceBaseMatrixSt)=nullity) and is(A.nullSpaceBaseMatrixSt = zeromatrix(m,length(ans5)+1))then flag5:true);
